import { purgeExpired } from "./src/lib/db/purge";
import type { SqlDatabase } from "./src/lib/db/sql";

// Generated by `opennextjs-cloudflare build`. Absent until that build runs.
// @ts-ignore
import handler from "./.open-next/worker.js";

type WorkerEnv = {
  DB?: SqlDatabase;
};

type ScheduledContext = {
  waitUntil(promise: Promise<unknown>): void;
};

type WorkerContext = ScheduledContext & {
  passThroughOnException?: () => void;
};

const CANONICAL_HOST = "seecabs.com";

function isCanonicalHost(hostname: string) {
  return hostname === CANONICAL_HOST;
}

export default {
  async fetch(request: Request, env: WorkerEnv, ctx: WorkerContext) {
    const url = new URL(request.url);
    if (url.hostname === `www.${CANONICAL_HOST}`) {
      url.hostname = CANONICAL_HOST;
      return Response.redirect(url.toString(), 301);
    }

    if (!isCanonicalHost(url.hostname) && url.pathname === "/robots.txt") {
      return new Response("User-agent: *\nDisallow: /\n", {
        headers: {
          "content-type": "text/plain; charset=utf-8",
          "cache-control": "public, max-age=0",
          "x-robots-tag": "noindex, nofollow",
        },
      });
    }

    const response: Response = await handler.fetch(request, env, ctx);
    if (isCanonicalHost(url.hostname)) return response;

    const headers = new Headers(response.headers);
    headers.set("x-robots-tag", "noindex, nofollow");
    return new Response(response.body, {
      status: response.status,
      statusText: response.statusText,
      headers,
    });
  },

  async scheduled(_controller: unknown, env: WorkerEnv, ctx: ScheduledContext) {
    if (!env.DB) return;
    ctx.waitUntil(
      purgeExpired(env.DB).catch((error: unknown) => {
        console.error("lead purge failed", error);
      }),
    );
  },
};
